<script setup>
import {computed,ref,reactive,watch} from 'vue';
import {activeTab,apiFetch,setActivePanelTab} from './store.js';
import MilestoneOptions from './MilestoneOptions.vue';
import {resolveMilestone} from './milestones.mjs';
import Icon from './HelmLabIcon.vue';
import DailyReadinessPanel from './DailyReadinessPanel.vue';
import IssueReadiness from './IssueReadiness.vue';
import {myWorkSnapshot as snapshot,myWorkLoading as loading,myWorkRefreshing as refreshing,myWorkError as error,refreshMyWork,pullMyWork} from './my-work-store.mjs';
import {testPackageSummaries,openTestPackage,createTestPackageFromIssue} from './test-packages-store.mjs';
import {myWorkRows,myWorkMetrics,filterMyWork,workTrend} from './my-work.mjs';
const form=reactive({repo:'rancher/rancher',milestone:0,scope:'mine',user:'',label:''}),milestones=ref([]),lookupBusy=ref(false),lookupError=ref(''),filter=ref('open'),query=ref(''),notice=ref('');
const milestoneText=ref(''),scopeOpen=ref(false);
const showMilestones=ref(false);
const selectedMilestone=computed(()=>resolveMilestone([...milestones.value,...(snapshot.value?.config.repo===form.repo?[snapshot.value.milestone]:[])],milestoneText.value));
const rows=computed(()=>myWorkRows(snapshot.value,testPackageSummaries.value)),metrics=computed(()=>myWorkMetrics(rows.value)),visible=computed(()=>filterMyWork(rows.value,filter.value,query.value));
const scopeChanged=computed(()=>snapshot.value&&['repo','milestone','scope','user','label'].some(key=>String(key==='milestone'?selectedMilestone.value?.number||0:form[key]).trim()!==String(snapshot.value.config[key]||'').trim()));
const cards=[{id:'open',label:'Remaining issues',tone:'blue'},{id:'needsPlan',label:'Need a test plan',tone:'amber'},{id:'needsReproduction',label:'Need reproduction',tone:'purple'},{id:'needsValidation',label:'Ready for validation',tone:'blue'},{id:'validated',label:'Validated · still open',tone:'green'},{id:'closed',label:'Closed on GitHub',tone:'green'}];
watch(()=>snapshot.value?.generatedAt,()=>{notice.value='';});
watch(()=>form.repo,()=>{milestones.value=[];form.milestone=0;milestoneText.value='';lookupError.value='';},{flush:'sync'});
watch(activeTab,async tab=>{if(tab==='my-work'){await refreshMyWork();scopeOpen.value=!snapshot.value;if(snapshot.value){Object.assign(form,snapshot.value.config);milestoneText.value=snapshot.value.milestone.title;}}}, {immediate:true});
async function lookup(){const repo=form.repo;lookupBusy.value=true;lookupError.value='';try{const response=await apiFetch('/api/issue-radar/milestones',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repo})});if(!response.ok)throw new Error(await response.text());const data=await response.json();if(repo!==form.repo)return;milestones.value=data.milestones||[];showMilestones.value=true;if(!milestones.value.length)lookupError.value='No milestones found in this repository.';return milestones.value;}catch(err){lookupError.value=err.message;}finally{lookupBusy.value=false;}}
async function pull(){if(loading.value||lookupBusy.value)return;notice.value='';lookupError.value='';if(!selectedMilestone.value){const items=await lookup();if(!items)return;}if(!selectedMilestone.value){lookupError.value=`No exact milestone matches “${milestoneText.value.trim()}”. Search the GitHub list and select a milestone.`;return;}try{const result=await pullMyWork({...form,milestone:selectedMilestone.value.number});Object.assign(form,result.config);milestoneText.value=result.milestone.title;scopeOpen.value=false;showMilestones.value=false;notice.value=`${result.created} starter ${result.created===1?'package':'packages'} created. Existing plans and package placement preserved.`;}catch{/* Shared error shown below. */}}
function open(row){if(row.pkg)openTestPackage(row.pkg.id);else createTestPackageFromIssue(row.issue);}
</script>
<template>
<div class="my-work">
 <header class="mw-hero"><div><span class="mw-eyebrow">Your milestone</span><h1>My Work<span class="mw-dot">.</span></h1><p>Your issues, test plans, and progress.</p></div><button class="mw-secondary" @click="setActivePanelTab('packages')"><Icon name="folder"/>Package library <Icon name="arrow"/></button></header>
 <DailyReadinessPanel/>
 <details class="mw-scope-shell mw-surface" :open="scopeOpen" @toggle="scopeOpen=$event.target.open"><summary>Milestone &amp; scope <span>{{snapshot?`${snapshot.config.repo} · ${snapshot.milestone.title}`:'Choose your work'}} · {{scopeOpen?'Collapse':'Edit'}}</span></summary><form class="mw-scope" @submit.prevent="pull"><div class="mw-scope-heading"><strong>Pull your milestone</strong><span>Reads GitHub · prepares local packages</span></div><div class="mw-fields"><label>Repository<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.repo" required placeholder="owner/repo" :disabled="loading||lookupBusy"/></label><div class="mw-milestone-field"><label for="mw-milestone">Milestone<input id="mw-milestone" v-model="milestoneText" type="text" required placeholder="2.16.0 or v2.16.0" :disabled="loading||lookupBusy" autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off"/></label><button type="button" class="mw-link" :disabled="lookupBusy||loading" @click="showMilestones?showMilestones=false:lookup()">{{lookupBusy?'Loading…':showMilestones?'Hide milestones':'Choose from GitHub'}}</button><MilestoneOptions v-if="showMilestones&&milestones.length" :items="milestones" :selected="selectedMilestone?.number||0" :disabled="loading||lookupBusy" @select="milestoneText=$event.title;showMilestones=false"/></div><label>Owner scope<select v-model="form.scope" :disabled="loading"><option value="mine">Assigned to me</option><option value="unassigned">Unassigned</option><option value="all">Entire milestone</option></select></label><label v-if="form.scope==='mine'">GitHub username<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.user" placeholder="Signed-in account by default" :disabled="loading"/></label><label>Labels · optional<input autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="off" v-model="form.label" placeholder="team/frameworks" :disabled="loading"/></label></div><div class="mw-scope-bottom"><p>Creates a milestone bucket and starter packages for open issues. Starters need your test cases. Existing packages stay intact.</p><button class="mw-primary" :disabled="loading||lookupBusy||!milestoneText.trim()">{{loading?'Pulling & preparing…':snapshot?'Refresh & prepare':'Pull & prepare'}}<Icon name="arrow"/></button></div><p v-if="lookupError" role="alert">{{lookupError}}</p></form></details>
 <div v-if="snapshot" class="mw-refresh-row"><span role="status">{{refreshing?'Refreshing ownership, QA labels, and issue state from GitHub…':'Refreshes when you return to My Work.'}}</span><button class="mw-secondary" :disabled="refreshing||loading" @click="refreshMyWork({force:true})">{{refreshing?'Refreshing…':'Refresh issues'}}</button></div>
 <p v-if="error" class="mw-alert" role="alert">{{error}}</p><p v-if="notice" class="mw-notice" role="status">{{notice}}</p>
 <template v-if="snapshot"><div class="mw-snapshot"><strong>{{snapshot.config.repo}} · {{snapshot.milestone.title}}</strong><span>{{snapshot.config.scope==='mine'?`@${snapshot.config.user}`:snapshot.config.scope==='unassigned'?'Unassigned':'Entire milestone'}} · {{snapshot.config.label||'All labels'}} · Snapshot {{new Date(snapshot.generatedAt).toLocaleString()}}</span></div><p v-if="scopeChanged" class="mw-alert">Settings changed. The charts and issues still show the saved snapshot above. Pull again to apply your changes.</p>
 <div class="mw-stats"><button v-for="card in cards" :key="card.id" :data-tone="card.tone" :aria-pressed="filter===card.id" @click="filter=card.id"><span>{{card.label}}</span><strong>{{metrics[card.id]}}</strong><small>View issues <Icon name="arrow"/></small></button></div>
 <div class="mw-charts"><section class="mw-surface"><div class="mw-section-heading"><div><span class="mw-eyebrow">Preparation coverage</span><h2>Make the next test ready.</h2></div><strong>{{metrics.planned}} / {{metrics.open}}</strong></div><div class="mw-coverage" role="img" :aria-label="`${metrics.planned} of ${metrics.open} open issues have saved test cases`"><i :style="{width:(metrics.open?metrics.planned/metrics.open*100:0)+'%'}"></i></div><div class="mw-legend"><button @click="filter='needsPlan'"><i class="mw-amber"></i>{{metrics.needsPlan}} need a plan</button><span><i class="mw-green"></i>{{metrics.planned}} have saved cases</span></div><p class="mw-caption">Coverage means cases are saved. Review their quality before testing.</p></section><section class="mw-surface"><span class="mw-eyebrow">Remaining work over time</span><h2>{{metrics.open}} open in this scope</h2><template v-if="snapshot.history?.length>1"><svg viewBox="-5 -5 310 95" role="img" :aria-label="`Open issue counts across ${snapshot.history.length} saved pulls: ${snapshot.history.map(point=>point.open).join(', ')}`"><path d="M0 80 H300" class="mw-axis"/><polyline :points="workTrend(snapshot.history)"/></svg><details class="mw-history"><summary>{{snapshot.history.length}} saved pulls · view counts</summary><ol><li v-for="point in snapshot.history" :key="point.at">{{new Date(point.at).toLocaleString()}} · {{point.open}} open · {{point.closed}} closed</li></ol></details></template><p v-else class="mw-caption mw-trend-empty">Your first snapshot is saved. Pull again to start seeing the trend.</p><p class="mw-caption">Issue counts for the selected scope; scope changes start a new trend.</p></section></div>
 <section class="mw-surface mw-queue"><div class="mw-section-heading"><div><span class="mw-eyebrow">Your next move</span><h2>{{cards.find(card=>card.id===filter)?.label||'All issues'}}</h2></div><div class="mw-queue-tools"><select v-model="filter" aria-label="Filter issues"><option value="">All issues</option><option value="qaNone">QA not required</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.label}}</option></select><input v-model="query" aria-label="Search issues" placeholder="Search title or #issue"/></div></div><div v-if="!visible.length" class="mw-empty"><Icon name="check"/><h3>Nothing in this view.</h3><p>{{rows.length?'Choose another stage or clear your search.':'No issues match this milestone and owner scope.'}}</p></div><article v-for="row in visible" :key="row.issue.number" class="mw-issue"><div class="mw-issue-number">#{{row.issue.number}}</div><div class="mw-issue-copy"><a :href="row.issue.html_url" target="_blank" rel="noopener noreferrer">{{row.issue.title}}</a><div><span class="mw-badge" :data-closed="row.closed">{{row.closed?'GitHub closed':'GitHub open'}}</span><span class="mw-badge">{{row.stage}}</span><span class="mw-caption">{{row.issue.assignees?.map(owner=>'@'+owner.login).join(', ')||'Unassigned'}}{{row.matches.length>1?` · ${row.matches.length} linked packages`:''}}</span></div></div><div class="mw-row-actions"><IssueReadiness :issue-url="row.issue.html_url" compact/><button class="mw-secondary" @click="open(row)">{{row.pkg?'Open package':'Create plan'}}<Icon name="arrow"/></button></div></article></section>
 <details v-if="snapshot.departed?.length" class="mw-surface mw-departed"><summary>{{snapshot.departed.length}} issues no longer in this scope</summary><p class="mw-caption">They may have moved milestones or changed ownership or labels. Their packages and bucket placement are preserved; move them in the library when ready.</p><div v-for="issue in snapshot.departed" :key="issue.number"><a :href="issue.html_url" target="_blank" rel="noopener noreferrer">#{{issue.number}} · {{issue.title}}</a></div></details>
 </template><section v-else class="mw-empty mw-surface"><Icon name="folder"/><h2>A home for the whole journey.</h2><p>Choose a milestone to bring in assigned work or prepare issues before they have an owner.</p><div class="mw-journey"><span>Discover</span><Icon name="arrow"/><span>Plan</span><Icon name="arrow"/><span>Reproduce</span><Icon name="arrow"/><span>Validate</span><Icon name="arrow"/><span>Close</span></div></section>
</div>
</template>
<style scoped>
.my-work{--mw-surface:var(--runway-card,#fff);--mw-text:var(--runway-ink,#203230);--mw-muted:var(--runway-muted,#657577);--mw-border:var(--runway-border,#dfe7e4);display:grid;gap:24px;color:var(--mw-text)}
:global(.dark) .my-work{--mw-surface:#1b2325;--mw-text:#e9f0ee;--mw-muted:#a0b3ae;--mw-border:#344541}
.mw-hero,.mw-section-heading,.mw-scope-heading,.mw-scope-bottom,.mw-snapshot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.mw-hero h1{font-size:clamp(36px,5vw,64px);letter-spacing:-.05em;font-weight:700;line-height:1.2}.mw-dot{color:#319476}.mw-hero p{color:var(--mw-muted);margin-top:10px;max-width:620px}.mw-eyebrow{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--mw-muted)}.mw-surface{background:var(--mw-surface);border:1px solid var(--mw-border);border-radius:20px;padding:24px}.mw-scope-heading span,.mw-snapshot span,.mw-caption,.mw-scope-bottom p{color:var(--mw-muted);font-size:12px}.mw-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:16px;margin:20px 0}.mw-milestone-field{display:grid;align-content:start;gap:8px;min-width:0}.mw-scope-shell>summary{cursor:pointer;font-weight:650;font-size:14px}.mw-scope-shell>summary span{font-size:12px;color:var(--mw-muted);font-weight:400;margin-left:15px}.mw-scope-shell[open]>summary{margin-bottom:24px}.mw-refresh-row{display:flex;gap:15px;justify-content:space-between;align-items:center;font-size:12px;color:var(--mw-muted)}.mw-fields label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600}input,select{background:var(--mw-surface);color:var(--mw-text);border:1px solid var(--mw-border);padding:10px 12px;border-radius:9px;min-width:0}.mw-primary,.mw-secondary{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:11px 15px;border-radius:10px;font-size:13px;font-weight:600}.mw-primary{background:#16735e;color:white}.mw-secondary{border:1px solid var(--mw-border);background:var(--mw-surface)}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #319476;outline-offset:3px}.mw-link{text-align:left;color:#319476;font-size:11px}.mw-scope-bottom p{max-width:630px}.mw-alert,.mw-notice{padding:14px 18px;border-radius:10px;background:#c08a2020;font-size:13px}.mw-notice{background:#31947618}.mw-stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.mw-stats button{text-align:left;background:var(--mw-surface);border:1px solid var(--mw-border);border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:12px}.mw-stats button[aria-pressed=true]{border-color:#319476;box-shadow:0 0 0 1px #319476}.mw-stats span{font-size:12px;color:var(--mw-muted);min-height:32px}.mw-stats strong{font-size:36px;line-height:1;font-weight:650;letter-spacing:-.04em}.mw-stats small{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--mw-muted)}.mw-charts{display:grid;grid-template-columns:1fr 1fr;gap:20px}h2{font-size:21px;font-weight:650;letter-spacing:-.03em;margin-top:5px}.mw-coverage{height:20px;border-radius:20px;background:#c08a2030;overflow:hidden;margin:28px 0 15px}.mw-coverage i{display:block;background:#319476;height:100%}.mw-legend{display:flex;justify-content:space-between;gap:15px;font-size:12px;margin-bottom:16px}.mw-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.mw-amber{background:#c08a20}.mw-green{background:#319476}.mw-charts svg{width:100%;height:95px;margin-top:12px}.mw-charts polyline{fill:none;stroke:#319476;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.mw-axis{stroke:var(--mw-border);fill:none}.mw-trend-empty{padding:30px 0}.mw-history{font-size:11px;margin-bottom:12px;color:var(--mw-muted)}.mw-history ol{max-height:160px;overflow:auto}.mw-queue-tools{display:flex;gap:10px;flex-wrap:wrap}.mw-issue{display:flex;align-items:center;gap:18px;padding:20px 0;border-top:1px solid var(--mw-border)}.mw-queue>.mw-section-heading{margin-bottom:22px}.mw-row-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.mw-issue-number{color:var(--mw-muted);font-size:12px;min-width:55px}.mw-issue-copy{flex:1;min-width:0}.mw-issue-copy>a{font-size:15px;font-weight:600}.mw-issue-copy>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:9px}.mw-badge{font-size:10px;padding:4px 8px;border-radius:5px;background:#31947612}.mw-badge[data-closed=true]{background:#7760ba20}.mw-empty{text-align:center;padding:50px 20px;color:var(--mw-muted)}.mw-empty>svg{margin:0 auto 14px;width:32px;height:32px}.mw-empty h2,.mw-empty h3{color:var(--mw-text);margin-bottom:10px}.mw-journey{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:28px;font-size:12px}.mw-departed summary{cursor:pointer;font-weight:600}.mw-departed p{margin:12px 0}.mw-departed a{font-size:13px}.mw-departed>div{margin-top:8px}@media(max-width:1100px){.mw-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.mw-charts{grid-template-columns:1fr}.mw-stats{grid-template-columns:repeat(2,1fr)}.mw-issue{flex-wrap:wrap}.mw-issue-copy{flex-basis:70%}.mw-surface{padding:18px}.mw-queue-tools{width:100%}.mw-queue-tools input{width:100%}}
</style>
